const b = $json.body || $json;
const patientId = String(b.patient_id || b.patientId || '').trim();
const encounterId = String(b.encounter_id || b.encounterId || '').trim();
const payer = String(b.payer || b.insurer || '').trim();
const total = Number(b.total_amount || b.totalAmount || 0);
const diagnosisCodes = Array.isArray(b.diagnosis_codes) ? b.diagnosis_codes : (b.diagnosisCodes || []);
const procedureCodes = Array.isArray(b.procedure_codes) ? b.procedure_codes : (b.procedureCodes || []);
const serviceDate = String(b.service_date || b.serviceDate || new Date().toISOString().slice(0, 10)).trim();
const ok = Boolean(patientId && encounterId && total > 0);
return [{ json: { ok, patientId, encounterId, payer, total, diagnosisCodes, procedureCodes, serviceDate, baseUrl: ($env.OPENEMR_BASE_URL || 'https://emr.hrthouse.com').replace(/\/$/, ''), siteId: $env.OPENEMR_SITE_ID || 'default', token: $env.OPENEMR_ACCESS_TOKEN || '', claimsWebhook: $env.CLAIMS_SUBMISSION_WEBHOOK_URL || '', patientBillingWebhook: $env.PATIENT_BILLING_WEBHOOK_URL || '', auditWebhook: $env.AUDIT_WEBHOOK_URL || '' } }];

const ctx = $json;
const claimId = `claim-${ctx.patientId}-${ctx.encounterId}-${Date.now()}`;
return [{ json: { ...ctx, claimId, claimPacket: { claim_id: claimId, patient_id: ctx.patientId, encounter_id: ctx.encounterId, payer: ctx.payer, total_amount: ctx.total, diagnosis_codes: ctx.diagnosisCodes, procedure_codes: ctx.procedureCodes, service_date: ctx.serviceDate, source: 'OpenEMR n8n claims submission' }, billingSummary: `Claim ${claimId} prepared for ${ctx.payer || 'payer queue'} at ${ctx.total}` } }];
